{
  "name": "opencode-handoff",
  "version": "0.7.0",
  "type": "module",
  "description": "Create focused handoff prompts for continuing work in new OpenCode sessions",
  "author": "Josh Thomas <josh@joshthomas.dev>",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "https://github.com/joshuadavidthomas/opencode-handoff"
  },
  "keywords": [
    "opencode",
    "plugin",
    "agent",
    "ai"
  ],
  "main": "./dist/index.js",
  "exports": {
    ".": "./dist/index.js",
    "./server": "./dist/index.js",
    "./tui": "./dist/tui.js"
  },
  "files": ["dist", "README.md"],
  "scripts": {
    "build": "bun build.ts",
    "prepack": "bun run build",
    "test": "bun test",
    "typecheck": "tsc --noEmit"
  },
  "dependencies": {
    "@opencode/plugin": "^2.1.2"
  },
  "peerDependencies": {
    "@opentui/core": ">=0.6.6",
    "@opentui/solid": ">=0.6.6",
    "solid-js": ">=1.9.0"
  },
  "peerDependenciesMeta": {
    "@opentui/core": { "optional": true },
    "@opentui/solid": { "optional": true },
    "solid-js": { "optional": true }
  },
  "devDependencies": {
    "@opentui/core": "^0.6.6",
    "@opentui/solid": "^0.6.6",
    "@types/bun": "latest",
    "@types/node": "^22.0.0",
    "solid-js": "^1.9.0",
    "typescript": "~5.9.3"
  },
  "engines": {
    "bun": ">=1.0.0"
  }
}
